#[test]
fn target_preview_is_transient_and_never_marks_the_document_dirty() {
    let document = AnimationSet::new(AssetId::generate());
    let canonical = document
        .to_canonical_json()
        .expect("Animation Set must serialize");
    let mut state = editor(document.clone());

    state.target_preview_skeleton = Some(AssetId::generate());

    assert_eq!(state.document, document);
    assert_eq!(
        state
            .document
            .to_canonical_json()
            .expect("Animation Set must serialize"),
        canonical
    );
    assert!(!state.is_dirty());
    assert!(!state.undo());
}

